export {};

// Module-local: the global `Emitter` fragment below extends it, and only this
// module's scope can resolve the name.
type __NodeEmitter = { emitNodeEvent(name: string): boolean };

// A module-local meaning of a name the *global* fragment's members use. The
// global fragment must keep resolving under the global scope.
interface Listener {
  readonly moduleOnly: number;
}

declare global {
  interface Emitter extends __NodeEmitter {}
}
